-- 0267 — Academy niveau 3, leçon 5 enrichie : le MACD, calcul, lecture et croisements mesurés sur la BRVM (2026-11-24).
--
-- Améliorations vérifiées :
--   · calcul pas à pas (paramètres réduits 3, 6, 3) et atelier interactif
--     « atelier_macd » avec scénario « cours figé (sans échange) » ;
--   · traduction des paramètres (12, 26, 9) dans le calendrier réel BRVM
--     (247 à 259 séances/an) et seuil minimal de 34 séances (BBGC : 10/11/2026) ;
--   · non-comparabilité en points de cours chiffrée sur quatre titres réels
--     au 23/11/2026 (ETIT −2,23 = −4,21 % vs SGBC −118,44 = −0,31 %) et MACD en % ;
--   · distinction histogramme / croisement signal / ligne zéro + divergences ;
--   · simulateur technique MACD enrichi : cours synchronisé au-dessus, curseurs
--     12/26/9, synthèse chiffrée dont MACD/cours (%) ;
--   · cas réel daté Orange Côte d’Ivoire (ORAC, oct.–nov. 2026) et piège SGBC ;
--   · 1 031 croisements MACD/Signal, 464 passages zéro et 1 783 ralentissements
--     mesurés sur les 10 valeurs les plus liquides (2021-2026, Wilson 95 %).
-- Source : frontend/lib/academy/contenus/niveau3/l05-macd.json, générée par
-- frontend/scripts/academy-lecon5-macd.mjs depuis
-- niveau3/sources/macd-brvm-2026-11-24.json (scripts/academy-lecon5-stats.mjs).
-- Testée : niveaux3-4.test.ts, simTechnique.test.ts, simulations-contenus.test.ts.
--
-- ⚠️ ORDRE : APRÈS le déploiement du frontend qui connaît le simulateur
-- « atelier_macd » et les champs « rapide / lente / signal ». Sans lui,
-- courseContentSchema refuse le cours et TOUT le niveau 3 répond 404.
--
-- Remplacement de la seule position 5 (leçons 0 à 4 avant elle), gardée par
-- titre (ancien OU nouveau, même préfixe) ; l’ordre des leçons ne change pas,
-- la progression reste valide. Fusion || : les clés absentes (image…) sont
-- conservées. Idempotente. Aucun schéma ne change ; aucune donnée personnelle.

begin;

do $do$
declare
  v_titre text;
begin
  select content->'lessons'->5->>'titre' into v_titre
    from public.academy_courses where slug = 'academy-niveau-3-technique' for update;
  if v_titre is null or v_titre not like 'Leçon 5 — Le MACD%' then
    raise exception '0267 : position 5 inattendue (%)', v_titre;
  end if;

  update public.academy_courses
     set content = jsonb_set(content, '{lessons,5}', (content->'lessons'->5) || $wb${"titre":"Leçon 5 — Le MACD : calcul, lecture et ce que valent ses croisements","module":"Module 2 — Indicateurs","categorie":"technical","duree_min":18,"sous_titre":"Deux moyennes exponentielles, leur écart, une ligne de signal et un histogramme : calcul pas à pas, divergences, cas réel Orange CI, et six ans de croisements mesurés à la BRVM.","resume":"Le MACD mesure l’écart entre une moyenne exponentielle courte et une longue. Quand l’écart grandit, la tendance accélère ; quand il se resserre, elle ralentit. Cette leçon construit ses trois composantes pas à pas, explique pourquoi deux actions ne se comparent pas en points de cours, présente l’histogramme et les divergences, puis met l’indicateur à l’épreuve sur la BRVM : un cas réel daté sur Orange Côte d’Ivoire, et 1 031 croisements mesurés depuis 2021 sur les valeurs les plus liquides.","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"Trois composantes, un calcul pas à pas","contenu":"Le MACD (moving average convergence divergence, ou convergence et divergence de moyennes mobiles) a été présenté par Gerald Appel à la fin des années 1970. Il prolonge directement la leçon 3 : il repose sur deux moyennes mobiles exponentielles du cours, une courte et une longue, et mesure l’écart entre elles.\nLa ligne MACD est la différence entre la moyenne exponentielle sur 12 séances (poids de la dernière clôture : 15,4 %) et celle sur 26 séances (poids : 7,4 %). Positive, elle indique une moyenne courte au-dessus de la longue ; négative, l’inverse. La ligne de signal est une moyenne exponentielle sur 9 séances de la ligne MACD elle-même (poids : 20,0 %) : elle la lisse.\nL’histogramme représente l’écart entre la ligne MACD et sa ligne de signal, sous forme de barres ; il a été ajouté plus tard par Thomas Aspray. Il exige d’abord 26 clôtures pour obtenir la première ligne MACD, puis 8 séances de plus pour la moyenne de signal, soit 34 séances cotées au total avant la première barre complète.\nLe tableau ci-dessous suit le calcul séance par séance sur des paramètres réduits (3, 6, 3) pour rester vérifiable à la main. Observez les séances 9 et 10 : le cours continue pourtant de monter (115 puis 116), mais l’histogramme diminue déjà (+0,56 puis +0,23). Il montre que la poussée ralentit avant même que le cours ne recule.","formules":[{"nom":"Ligne MACD","expression":"Moyenne exponentielle 12 − Moyenne exponentielle 26","exemple":"105 − 102 = +3 : la moyenne courte est au-dessus de la longue"},{"nom":"Ligne de signal","expression":"Moyenne exponentielle sur 9 séances de la ligne MACD","exemple":"Elle lisse la ligne MACD (poids de 20,0 % à la dernière valeur)"},{"nom":"Histogramme","expression":"Ligne MACD − Ligne de signal","exemple":"Positif et croissant : l’élan haussier se renforce"},{"nom":"Séances minimales","expression":"Lente + Signal − 1","exemple":"26 + 9 − 1 = 34 séances avant la première barre d’histogramme"}],"tableau":{"colonnes":["Séance","Clôture","EMA 3","EMA 6","MACD","Signal 3","Histogramme","Lecture"],"lignes":[["S1","100","—","—","—","—","—","Moins de 6 clôtures"],["S2","100","—","—","—","—","—","Moins de 6 clôtures"],["S3","101","100,33","—","—","—","—","Moins de 6 clôtures"],["S4","102","101,17","—","—","—","—","Moins de 6 clôtures"],["S5","103","102,08","—","—","—","—","Moins de 6 clôtures"],["S6","105","103,54","101,83","+1,71","—","—","Première ligne MACD"],["S7","108","105,77","103,60","+2,18","—","—","Signal encore indisponible"],["S8","112","108,89","106,00","+2,89","+2,26","+0,63","Premier histogramme"],["S9","115","111,94","108,57","+3,37","+2,82","+0,56","Hausse, mais histogramme fléchit"],["S10","116","113,97","110,69","+3,28","+3,05","+0,23","Sommet du cours, élan resserré"],["S11","114","113,99","111,64","+2,35","+2,70","−0,35","Croisement baissier (signal)"],["S12","111","112,49","111,46","+1,04","+1,87","−0,83","Baisse accélère, MACD encore > 0"]],"note":"Valeurs d’exemple, paramètres réduits (3, 6, 3) calculés avec les formules exactes de WESTBOURSE. Le même décalage vaut en (12, 26, 9) : 25 séances sans MACD, 33 sans histogramme."},"simulation":{"type":"atelier_macd","consigne":"Modifiez une clôture ou cliquez sur « Tester un cours figé » : regardez la ligne MACD et l’histogramme basculer en négatif sans aucune baisse de prix.","clotures":[100,100,101,102,103,105,108,112,115,116,114,111],"rapide":3,"lente":6,"signal":3}},{"type":"importance","titre":"Pourquoi 12, 26 et 9 ? Et pourquoi deux actions ne se comparent pas","contenu":"Les paramètres 12, 26 et 9 viennent des marchés où l’indicateur a été conçu, mais ils se traduisent simplement dans le calendrier de la BRVM. Avec 247 à 259 séances par an entre 2021 et 2025 (environ 21 par mois), 12 séances couvrent un peu plus de deux semaines, 26 séances un peu plus d’un mois de cotation, et 9 séances près de deux semaines.\nComme pour les moyennes mobiles, ce sont des conventions partagées, pas des lois : elles rendent les lectures comparables d’un outil à l’autre. Une valeur récemment introduite n’a pas tout de suite de MACD complet : Bridge Bank Group Côte d’Ivoire (BBGC), admise le 24 septembre 2026, n’a obtenu sa première barre d’histogramme qu’à sa 34e séance, le 10 novembre 2026.\nContrairement au RSI (borné de 0 à 100), le MACD s’exprime en points de cours, donc en FCFA. Sa valeur brute dépend directement du prix de l’action. Le 23 novembre 2026, le MACD de Société Générale CI (SGBC, 37 610 FCFA) valait −118,44 FCFA, soit 53 fois plus en valeur absolue que celui d’ETI Togo (ETIT, 53 FCFA, MACD −2,23 FCFA). Rapporté au cours, l’écart d’ETIT (−4,21 %) était pourtant 14 fois plus fort que celui de SGBC (−0,31 %).\nOn compare donc le MACD d’une action à son propre passé, jamais à celui d’une autre. Pour comparer deux titres entre eux, il faut rapporter l’écart au cours, en pourcentage (un indicateur appelé PPO, percentage price oscillator).","formules":[{"nom":"MACD rapporté au cours (%)","expression":"(Ligne MACD ÷ Cours de clôture) × 100","exemple":"−2,23 ÷ 53 = −4,21 % pour ETIT contre −118,44 ÷ 37 610 = −0,31 % pour SGBC"}],"stats":[{"label":"12 séances","valeur":"≈ 2,5 sem.","detail":"moyenne courte, poids 15,4 % à la clôture"},{"label":"26 séances","valeur":"≈ 1,2 mois","detail":"moyenne longue, poids 7,4 % à la clôture"},{"label":"34 séances","valeur":"Seuil minimal","detail":"26 + 9 − 1 avant le premier histogramme"}],"tableau":{"colonnes":["Valeur","Clôture (FCFA)","Ligne MACD (FCFA)","MACD rapporté au cours","Lecture"],"lignes":[["ETIT (Ecobank TI)","53","−2,23","−4,21 %","Petit en FCFA, fort en pourcentage"],["SGBC (Société Générale CI)","37 610","−118,44","−0,31 %","Grand en FCFA, très faible en %"],["ORAC (Orange CI)","19 005","−526,61","−2,77 %","Écart marqué sur les deux échelles"],["NSBC (NSIA Banque CI)","15 000","−1 351,84","−9,01 %","Plus fort écart relatif des quatre"]],"note":"Clôtures publiées par la BRVM au 23 novembre 2026 (base WESTBOURSE) ; MACD (12, 26, 9) calculé par WESTBOURSE."}},{"type":"definition","titre":"Lire l’histogramme, les croisements et la ligne zéro","contenu":"Le MACD se lit à trois niveaux, du plus réactif au plus lent. Le premier est l’évolution de l’histogramme, qui décrit l’accélération ou le ralentissement de la tendance selon deux critères : son signe et sa pente. Positif et croissant, la hausse accélère ; positif et décroissant, elle ralentit. Les deux cas symétriques décrivent la baisse.\nLe deuxième niveau est le croisement entre la ligne MACD et sa ligne de signal, qui correspond exactement au passage de l’histogramme par zéro. Beaucoup le traitent comme un signal d’achat ou de vente : il hérite pourtant du retard des deux moyennes exponentielles et arrive souvent après le début du mouvement.\nLe troisième niveau est le franchissement de la ligne zéro par la ligne MACD elle-même. Comme la ligne MACD vaut EMA 12 moins EMA 26, son passage au-dessus de zéro signifie que la moyenne exponentielle 12 séances passe au-dessus de la 26 : c’est un croisement de moyennes mobiles, plus lent et moins fréquent que le croisement avec la ligne de signal.","tableau":{"colonnes":["Ce que l’on observe","Ce que cela décrit","Réactivité"],"lignes":[["Histogramme positif et croissant","La tendance haussière s’accélère","Précoce (bruité)"],["Histogramme positif et décroissant","La hausse ralentit","Précoce (souvent démenti)"],["Histogramme négatif et décroissant","La tendance baissière s’accélère","Précoce (bruité)"],["Histogramme négatif et croissant","La baisse ralentit","Précoce (souvent démenti)"],["Ligne MACD croise la ligne de signal","L’histogramme change de signe (croisement court)","Intermédiaire"],["Ligne MACD franchit la ligne zéro","EMA 12 croise EMA 26 (tendance sur ~1 mois)","Plus lent, plus rare"]],"note":"Des descriptions du passé. Aucune ligne de ce tableau n’est une raison d’acheter ou de vendre."},"graphiques":[{"type":"bar","titre":"Les quatre phases d’un histogramme de MACD (exemple)","labels":["S1","S2","S3","S4","S5","S6","S7","S8"],"valeurs":[-3,-2,-0.5,1,2.5,3,2,0.5],"unite":"","note":"Valeurs d’exemple. Négatif et croissant (S1 à S3) : la baisse ralentit. Il devient positif à S4 (croisement MACD/Signal), grandit jusqu’à S6 (la hausse accélère), puis diminue (la hausse ralentit). Aucune de ces phases ne dit combien de temps durera la suivante.","reel":false}],"encadres":[{"ton":"info","titre":"Deux croisements à ne pas confondre","texte":"Un croisement MACD/Signal qui se produit sous la ligne zéro décrit un rebond d’élan dans une tendance encore orientée à la baisse (EMA 12 reste sous EMA 26). Un croisement au-dessus de zéro décrit une reprise d’élan dans une tendance déjà haussière. La mesure présentée plus bas vérifie si cette distinction améliore les résultats à la BRVM."}]},{"type":"definition","titre":"Les divergences : quand le cours et l’élan ne racontent plus la même histoire","contenu":"Une divergence apparaît quand le cours et le MACD évoluent dans des directions opposées d’un sommet ou d’un creux au suivant. Dans une divergence baissière, le cours atteint un nouveau sommet plus haut que le précédent, mais la ligne MACD (ou l’histogramme) forme un sommet moins élevé : la hausse se poursuit, mais avec moins d’élan qu’avant.\nDans une divergence haussière, c’est l’inverse : le cours touche un nouveau plus-bas, tandis que le MACD forme un creux moins profond. La pression baissière ralentit, même si le prix recule encore. Sur le graphique d’exemple ci-dessous, le cours monte de 122 (S9) à 125 (S17), mais la ligne MACD passe d’un pic de +4,74 à +1,79.\nLes divergences sont l’usage le plus commenté du MACD — et une source fréquente de déception. Une divergence signale une perte d’élan, pas un retournement garanti : dans une tendance forte, le cours peut enchaîner deux ou trois nouveaux sommets successifs avec un MACD qui s’essouffle avant de corriger réellement.","graphiques":[{"type":"line","titre":"Une divergence baissière : nouveau sommet du cours, sommet plus bas du MACD (exemple)","labels":["S8","S9","S10","S11","S12","S13","S14","S15","S16","S17","S18","S19","S20"],"series":[{"nom":"Clôture","valeurs":[119,122,120,118,117,119,121,123,124,125,123,120,117],"axe":"gauche"},{"nom":"Ligne MACD","valeurs":[4.6,4.74,3.68,2.35,1.33,1.2,1.41,1.71,1.79,1.78,1.09,0.05,-0.98],"axe":"droite"}],"unite":"FCFA","unite_droite":"MACD","note":"Valeurs d’exemple (calculées en MACD 3, 6, 3). Le cours marque un second sommet plus haut (125 à S17 contre 122 à S9), tandis que la ligne MACD culmine nettement plus bas (+1,79 contre +4,74) : la poussée haussière perd de son élan.","reel":false}],"encadres":[{"ton":"attention","titre":"Divergence ne veut pas dire retournement immédiat","texte":"Agir dès qu’une divergence se dessine revient souvent à sortir trop tôt d’une hausse ou à entrer trop tôt dans une baisse. Elle se lit comme une alerte de contexte, à croiser avec les niveaux de prix, les volumes et un niveau d’invalidation (leçon 0)."}]},{"type":"cas","titre":"Sur la BRVM : le MACD en direct","reel":true,"contenu":"Le simulateur ci-dessous calcule le MACD sur les clôtures réelles de six valeurs très échangées de la BRVM, avec le cours de clôture synchronisé au-dessus pour situer chaque croisement par rapport au mouvement réel du prix.\nEssayez deux manipulations. D’abord, passez d’une valeur à faible cours nominal (ETIT) à une valeur à cours élevé (SGBC) et observez l’échelle verticale : le MACD change d’ordre de grandeur, mais son rapport au cours en pourcentage reste comparable. Ensuite, raccourcissez les moyennes (par exemple 6, 13, 5) : les croisements arrivent plus tôt, mais se multiplient.\nLe tableau en direct, en dessous, donne pour les mêmes valeurs les moyennes mobiles 20 et 50 séances et le RSI 14 : le MACD se lit toujours dans ce contexte plus large.","simulation":{"type":"technique","indicateur":"macd","consigne":"Changez de valeur ou ajustez les trois réglages (rapide, lente, signal) : le cours s’affiche au-dessus du MACD pour mesurer le retard des croisements.","codes":["SNTS","ORAC","SGBC","SIBC","ETIT","BOAC"],"rapide":12,"lente":26,"signal":9},"donnees_reelles":{"vue":"technique","codes":["SNTS","ORAC","SGBC","SIBC","ETIT","BOAC"]}},{"type":"cas","titre":"Un cas réel : Orange Côte d’Ivoire (ORAC), octobre–novembre 2026","reel":true,"contenu":"Entre le 28 octobre et le 23 novembre 2026, Orange Côte d’Ivoire (ORAC) montre en moins d’un mois toutes les phases de lecture du MACD. Le 29 octobre, la ligne MACD croise sa ligne de signal à la hausse (histogramme à +6,3), alors même que le cours recule ce jour-là de 21 500 à 21 000 FCFA : le croisement hérite du rebond des séances précédentes.\nLe 2 novembre, la ligne MACD franchit zéro (+1,4) et l’histogramme grandit jusqu’au 4 novembre (+95,5), où le cours plafonne à 21 500 FCFA. Dès le 5 novembre, l’histogramme commence à se resserrer (+70,0 puis +25,4 le 9 novembre) : la poussée ralentit cinq jours avant la cassure.\nLe 10 novembre, le cours décroche de 4,8 % à 20 000 FCFA (2 197 titres échangés) : la ligne MACD passe à la fois sous sa ligne de signal et sous zéro. L’histogramme creuse ensuite jusqu’au 18 novembre (−213,7) alors que le cours atteint 19 000 FCFA avec un pic de 10 360 titres le 17 novembre. Du 19 au 23 novembre, l’histogramme remonte vers zéro (−151,4) : la baisse ralentit, sans dire si elle s’arrêtera.","tableau":{"colonnes":["Séance","Clôture (FCFA)","Titres échangés","Ligne MACD","Signal","Histogramme","Lecture"],"lignes":[["28/10","21 500","1 754","−113,8","−97,4","−16,4","Baisse ralentit"],["29/10","21 000","828","−89,5","−95,9","+6,3","Croisement haussier (en retard)"],["02/11","21 450","4 101","+1,4","−68,4","+69,7","Passage au-dessus de zéro"],["04/11","21 500","1 779","+72,9","−22,5","+95,5","Pic de l’histogramme"],["05/11","21 100","2 383","+65,0","−5,0","+70,0","Hausse ralentit"],["09/11","21 000","379","+37,7","+12,3","+25,4","Écart se resserre"],["10/11","20 000","2 197","−52,1","−0,6","−51,5","Double croisement baissier"],["13/11","19 500","5 341","−254,8","−94,9","−159,9","Baisse accélère"],["17/11","19 000","10 360","−396,9","−190,3","−206,6","Pic de volume, baisse accélère"],["18/11","19 000","1 237","−457,4","−243,7","−213,7","Creux de l’histogramme"],["20/11","19 250","660","−507,0","−337,3","−169,7","Baisse ralentit"],["23/11","19 005","2 509","−526,6","−375,2","−151,4","Baisse ralentit"]],"note":"Clôtures et titres échangés publiés par la BRVM (sélection de 12 séances entre le 28/10 et le 23/11/2026) ; MACD (12, 26, 9) calculé par WESTBOURSE (base lue le 24/11/2026). Un cas daté : le simulateur ci-dessous montre la situation d’aujourd’hui."},"simulation":{"type":"technique","indicateur":"macd","consigne":"La même valeur, en direct : comparez le cours de clôture (en haut) aux croisements de l’histogramme et de la ligne zéro (en bas).","codes":["ORAC"],"rapide":12,"lente":26,"signal":9},"donnees_reelles":{"vue":"technique","codes":["ORAC"]}},{"type":"importance","titre":"Ce que valent les croisements du MACD à la BRVM","contenu":"Nous avons mesuré tous les croisements du MACD (12, 26, 9) sur les dix valeurs les plus liquides de la BRVM (71,9 % des capitaux échangés), du 4 janvier 2021 au 23 novembre 2026 : 1 031 croisements MACD/Signal (514 haussiers, 517 baissiers), soit environ 21 par valeur et par an — trois fois et demie plus que les croisements de moyennes 20/50 de la leçon 3.\nLe premier constat est le nombre d’allers-retours : 37,1 % des croisements MACD/Signal se défont en 5 séances ou moins, 55,3 % en 10 séances, et 81,1 % en 20 séances. Le retard se chiffre aussi : au croisement haussier, le cours avait déjà monté de +6,1 % depuis son plus-bas des 26 séances précédentes (médiane) ; au croisement baissier, déjà perdu 4,0 % depuis son plus-haut.\nVingt séances après un croisement, le cours n’a pas bougé plus souvent dans son sens qu’après une séance quelconque. Sur 12 238 séances mesurées, il était plus haut 20 séances plus tard dans 58,2 % des cas, plus bas dans 34,1 %. Après un croisement haussier MACD/Signal, il était plus haut dans 49,4 % des cas (moins souvent qu’une séance quelconque, sur 2021-2023 comme sur 2024-2026) ; après un baissier, plus bas dans 33,2 % (écart non établi).\nDeux règles classiques des manuels ont été testées sur les mêmes données. Filtrer les croisements haussiers selon la ligne zéro (sous zéro : 52,1 % ; au-dessus : 47,4 %) ou attendre le franchissement de zéro (464 cas, 52,4 % à la hausse, 26,6 % à la baisse) ne fait jamais mieux qu’une séance quelconque. Quant au ralentissement précoce de l’histogramme (1 783 cas), il devance le croisement de 5 séances en médiane, mais est démenti avant zéro dans 36,0 % des cas.\nCette mesure a ses limites : elle porte sur les dix valeurs les plus liquides (sur les titres peu échangés, le bruit est plus fort encore), les cas contemporains sur plusieurs titres ne sont pas indépendants, et ni frais ni dividendes ne sont inclus. Retenez l’ordre de grandeur : à la BRVM, un croisement du MACD constate une variation d’élan passée ; pris seul, il n’annonce pas la suite.","stats":[{"label":"Croisements MACD/Signal","valeur":"1 031","detail":"≈ 21 par valeur et par an, 2021-2026"},{"label":"Défaits en 10 séances","valeur":"55,3 %","detail":"37,1 % dès 5 séances · 81,1 % en 20 séances"},{"label":"Déjà parcouru au croisement haussier","valeur":"+6,1 %","detail":"depuis le plus-bas des 26 séances, médiane"},{"label":"Ralentissements démentis","valeur":"36,0 %","detail":"avant zéro (5 séances d’avance sinon)"}],"tableau":{"colonnes":["Signal mesuré","Cas","Sens attendu","Part, 20 séances après","Séance quelconque","Intervalle à 95 %","Verdict"],"lignes":[["MACD / Signal — Haussier","508","Hausse","49,4 %","58,2 %","45,1 à 53,7 %","Moins souvent qu’une séance quelconque"],["MACD / Signal — Baissier","509","Baisse","33,2 %","34,1 %","29,3 à 37,4 %","Écart non établi"],["Passage ligne zéro — Haussier","225","Hausse","52,4 %","58,1 %","45,9 à 58,9 %","Écart non établi"],["Passage ligne zéro — Baissier","229","Baisse","26,6 %","34,1 %","21,3 à 32,7 %","Moins souvent qu’une séance quelconque"]],"note":"Part des cas où le cours, 20 séances après le croisement, était dans le sens attendu. Intervalle de Wilson à 95 %, au moins 30 cas. Sources : clôtures des 10 actions les plus liquides de la BRVM du 04/01/2021 au 23/11/2026 (base WESTBOURSE, lue le 24/11/2026) ; MACD (12, 26, 9) et croisements calculés par WESTBOURSE."},"tableaux":[{"colonnes":["Découpage (croisements MACD/Signal)","Haussier : plus haut 20 séances après","Baissier : plus bas 20 séances après"],"lignes":[["2021 à 2023","48,7 % contre 55,3 % (263 cas) : moins souvent","32,6 % contre 34,9 % (261 cas) : écart non établi"],["2024 à 2026","50,2 % contre 60,8 % (245 cas) : moins souvent","33,9 % contre 33,4 % (248 cas) : écart non établi"],["Croisement sous la ligne zéro","52,1 % contre 58,2 % (219 cas) : écart non établi","19,2 % contre 34,1 % (130 cas) : moins souvent"],["Croisement au-dessus de la ligne zéro","47,4 % contre 58,2 % (289 cas) : moins souvent","38,0 % contre 34,1 % (379 cas) : écart non établi"]],"note":"Chaque sous-période est comparée à ses propres séances quelconques. « Écart non établi » : l’intervalle à 95 % contient la part d’une séance quelconque."}],"graphiques":[{"type":"bar","titre":"Après le croisement MACD, le cours est-il allé dans son sens plus souvent ? (%, 20 séances après)","labels":["Signal, haussier","Signal, baissier","Zéro, haussier","Zéro, baissier"],"series":[{"nom":"Après le croisement","valeurs":[49.4,33.2,52.4,26.6]},{"nom":"Séance quelconque","valeurs":[58.2,34.1,58.1,34.1]}],"unite":"%","note":"Dans chaque paire, la barre « après le croisement » n’est jamais au-dessus de celle d’une séance quelconque. Sources : clôtures des 10 actions les plus liquides de la BRVM du 04/01/2021 au 23/11/2026 (base WESTBOURSE, lue le 24/11/2026) ; MACD (12, 26, 9) et croisements calculés par WESTBOURSE.","reel":true}],"encadres":[{"ton":"cle","titre":"Ce que cela veut dire pour vous","texte":"Le MACD reste utile pour lire le rythme d’une tendance : il montre si un mouvement accélère ou s’essouffle, et aide à éviter de courir après une hausse déjà essoufflée. Un croisement seul ne justifie ni un achat ni une vente : la grille de décision de la leçon 0 demande toujours la tendance de fond, les niveaux de prix, les volumes et un niveau d’invalidation."}]},{"type":"piege","titre":"Les cinq pièges du MACD à la BRVM","contenu":"Construit sur deux moyennes exponentielles, le MACD hérite de leurs défauts et en ajoute un propre à son calcul : sans mouvement de cours, ses deux courbes se rattrapent mécaniquement. Sur la BRVM, cinq pièges reviennent régulièrement.","points":[{"titre":"Les allers-retours en marché sans direction","detail":"Dans un marché qui oscille, les croisements s’enchaînent. Sur Société Générale CI (SGBC), du 29 octobre au 9 novembre 2026, le cours évolue dans un couloir de 3,9 % (38 505 à 39 990 FCFA) : en huit séances, le MACD déclenche quatre croisements successifs (haussier le 29/10, baissier le 02/11, haussier le 06/11 sur 358 titres, baissier dès le 09/11).","verifier":"La pente de la moyenne 50 séances et l’amplitude du couloir des prix récents."},{"titre":"Le retard intégré","detail":"Au moment d’un croisement haussier MACD/Signal sur les dix valeurs liquides (2021-2026), le cours avait déjà pris +6,1 % en médiane depuis son plus-bas des 26 séances.","verifier":"La distance déjà parcourue par le cours depuis le dernier creux ou sommet."},{"titre":"Comparer deux actions en points de cours","detail":"Le 23 novembre 2026, un MACD de −118,44 FCFA sur SGBC (37 610 FCFA) représente −0,31 % du cours ; −2,23 FCFA sur ETIT (53 FCFA) représentent −4,21 %.","verifier":"Toujours rapporter le MACD au cours de l’action (en %), ou ne le comparer qu’à son propre passé."},{"titre":"Les séances sans échange : un faux croisement mécanique","detail":"Si un cours monte de 10 000 à 12 000 FCFA puis reste figé sans échange, l’EMA 12 rattrape 12 000 plus vite que l’EMA 26 : au bout de 11 séances figées, l’histogramme atteint zéro puis passe négatif sans qu’un seul vendeur n’ait fait baisser le prix. Sur des titres figés 50 séances (SEMC et SICC du 16/09 au 24/11/2026), le MACD vaut exactement zéro.","verifier":"Les volumes récents sur la fiche de la valeur, et sa classe de liquidité."},{"titre":"Le détachement d’un dividende","detail":"Le jour du détachement d’un dividende important, le cours baisse mécaniquement du montant du coupon. L’EMA 12 réagit deux fois plus vite que l’EMA 26 : le MACD et l’histogramme plongent brutalement, ce qui reflète le dividende et non un retournement de tendance.","verifier":"Le calendrier des dividendes WESTBOURSE avant d’interpréter un plongeon soudain du MACD."}]},{"type":"retenir","titre":"L’essentiel : moyennes mobiles, RSI ou MACD ?","contenu":"Le MACD mesure un élan, pas une destination. Il dit si une tendance accélère ou ralentit ; il ne dit ni jusqu’où elle ira, ni quand elle s’arrêtera.\nIl complète les moyennes mobiles (leçon 3) et le RSI (leçon 4) sans les remplacer : chacun répond à une question différente. Lus ensemble avec les volumes, ils décrivent l’état d’un graphique. Aucun des trois ne dit si la société mérite votre argent : cette réponse reste dans ses comptes (niveau 2).","tableau":{"colonnes":["Indicateur","Question posée","Échelle","Ce qu’il montre bien","Limite principale"],"lignes":[["Moyennes mobiles (20 / 50)","Quelle est la direction ?","Prix (FCFA)","Tendance de fond, lissage du bruit","Retard fort, croisements tardifs"],["RSI (14)","Le mouvement récent est-il excessif ?","0 à 100 (comparable)","Intensité récente, zones extrêmes","Peut rester en excès longtemps"],["MACD (12, 26, 9)","La tendance accélère-t-elle ou ralentit-elle ?","Points de cours (non comparable)","Rythme, essoufflement, divergences","21 croisements/an, 55 % défaits en 10 séances"]],"note":"Synthèse du Module 2 : trois indicateurs, trois questions complémentaires. Aucun ne prévoit le cours de demain."},"points":[{"titre":"Trois composantes","detail":"MACD = EMA 12 − EMA 26 ; Signal = EMA 9 du MACD ; Histogramme = MACD − Signal (34 séances minimales)."},{"titre":"Lire l’histogramme","detail":"Signe et pente montrent si la hausse ou la baisse accélère ou ralentit ; le changement de signe correspond au croisement MACD/Signal."},{"titre":"Ne jamais comparer entre actions","detail":"Exprimé en FCFA, le MACD se compare à son propre historique ou se rapporte au cours en pourcentage."},{"titre":"Les croisements, mesurés à la BRVM","detail":"Près de 21 par an sur les valeurs liquides, plus de la moitié défaits en 10 séances, sans avantage établi à 20 séances face à une séance quelconque."},{"titre":"Toujours vérifier le contexte BRVM","detail":"Un cours figé fabrique mécaniquement un croisement baissier ; un détachement de dividende fausse l’indicateur pendant plusieurs semaines."}]}],"charts":[],"quiz":[{"question":"La moyenne exponentielle 12 vaut 250 et la 26 vaut 240. Que vaut la ligne MACD ?","options":["−10","+10","490","250"],"correct":1,"explication":"250 − 240 = +10."},{"question":"Combien de séances cotées faut-il au minimum pour afficher la première barre d’histogramme d’un MACD (12, 26, 9) ?","options":["9 séances","12 séances","26 séances","34 séances"],"correct":3,"explication":"Il faut 26 séances pour obtenir la première ligne MACD, puis 8 séances supplémentaires pour la moyenne de signal sur 9 valeurs (26 + 9 − 1 = 34)."},{"question":"Dans le calendrier de la BRVM (environ 21 séances par mois), à quelle durée correspond la moyenne longue de 26 séances du MACD ?","options":["Un peu plus d’un mois de cotation","Un peu moins d’une semaine de cotation","Environ un trimestre complet de cotation","Presque une année entière de cotation"],"correct":0,"explication":"26 séances sur environ 21 séances par mois représentent environ 1,2 mois de cotation."},{"question":"Pourquoi ne pas comparer directement le MACD de deux actions différentes en FCFA ?","options":["Parce que l’indicateur est confidentiel","Parce qu’il est borné entre 0 et 100","Parce que sa valeur dépend du prix de l’action","Parce qu’il ne se calcule que sur les banques"],"correct":2,"explication":"Le MACD s’exprime en points de cours : −2,23 FCFA sur ETIT (53 FCFA) pèsent −4,21 %, tandis que −118,44 FCFA sur SGBC (37 610 FCFA) ne pèsent que −0,31 %."},{"question":"L’histogramme du MACD est positif, mais diminue d’une séance à l’autre. Que décrit-il ?","options":["Une hausse qui ralentit","Une hausse qui accélère","Une baisse qui accélère","Un arrêt de cotation"],"correct":0,"explication":"L’histogramme reste positif, mais l’écart entre la ligne MACD et sa ligne de signal se resserre : la hausse ralentit."},{"question":"Que signifie le passage de la ligne MACD au-dessus de zéro ?","options":["Le cours vient de doubler en une séance","L’action verse un dividende exceptionnel","La moyenne exponentielle 12 passe au-dessus de la 26","Le RSI vient de franchir le seuil de 70"],"correct":2,"explication":"Par définition, MACD = EMA 12 − EMA 26. Il devient positif au moment exact où la moyenne exponentielle 12 séances passe au-dessus de la 26."},{"question":"Qu’appelle-t-on une divergence baissière sur le MACD ?","options":["Le cours baisse pendant que le MACD baisse plus vite","Le cours fait un sommet plus haut, le MACD un sommet plus bas","Les deux moyennes exponentielles restent parfaitement parallèles","Le volume augmente fortement lors d’une séance sans variation"],"correct":1,"explication":"Le cours inscrit un nouveau plus-haut mais l’élan mesuré par le MACD est moins élevé : c’est un signe d’essoufflement, pas une garantie de retournement."},{"question":"Sur les dix valeurs les plus liquides de la BRVM (2021-2026), quelle part des croisements MACD/Signal s’est défaite dans les 10 séances suivantes ?","options":["Environ 5 %","Environ 15 %","Environ 95 %","Environ 55 %"],"correct":3,"explication":"55,3 % des croisements MACD/Signal (567 sur 1 026) ont été suivis d’un croisement inverse dans les 10 séances suivantes."},{"question":"Sur les mêmes données (2021-2026), que se passe-t-il après un ralentissement précoce de l’histogramme ?","options":["Il garantit un croisement dès la séance suivante","Il n’arrive presque jamais sur les actions liquides","Il précède le croisement de 5 séances, mais est démenti dans 36 % des cas","Il arrive toujours plusieurs séances après le croisement de la ligne zéro"],"correct":2,"explication":"Sur 1 783 cas mesurés, le ralentissement devance le croisement de 5 séances en médiane quand il aboutit, mais repart dans le sens initial avant zéro dans 36,0 % des cas."},{"question":"Après une hausse, le cours d’une action peu liquide reste figé sans aucun échange pendant 10 séances. Que fait son MACD ?","options":["Ses courbes se rejoignent et l’histogramme peut devenir négatif","Il reste bloqué à sa valeur maximale jusqu’au prochain échange","Il continue de monter tant que personne ne vend de titres","Il disparaît automatiquement du graphique de la valeur"],"correct":0,"explication":"Sur un cours constant, l’EMA 12 rejoint le prix plus vite que l’EMA 26, puis la ligne MACD recule vers zéro et passe sous sa ligne de signal : un faux croisement baissier sans aucun vendeur."},{"question":"Le jour du détachement d’un dividende important, le cours baisse du montant du coupon. Quel est l’effet sur le MACD ?","options":["Aucun effet, le MACD corrige automatiquement les dividendes","Il chute brusquement, car l’EMA 12 réagit plus vite que l’EMA 26","Il monte fortement en raison de l’entrée d’argent des actionnaires","Il passe immédiatement à exactement zéro dès la clôture"],"correct":1,"explication":"L’EMA 12 absorbe la baisse mécanique deux fois plus vite que l’EMA 26, créant un plongeon qui reflète le dividende et non une vague de ventes."},{"question":"Comment le MACD complète-t-il le RSI ?","options":["Il le remplace car il mesure aussi sur une échelle de 0 à 100","Il calcule le bénéfice par action de la société cotée","Il supprime le retard propre aux moyennes mobiles","Le RSI mesure l’excès récent ; le MACD, l’accélération de la tendance"],"correct":3,"explication":"Deux questions complémentaires : l’intensité récente sur une échelle fixe (RSI) et la dynamique de tendance en points de cours (MACD)."}],"qcm":{"question":"La moyenne exponentielle 12 vaut 250 et la 26 vaut 240. Que vaut la ligne MACD ?","options":["−10","+10","490","250"],"correct":1,"explication":"250 − 240 = +10."},"liens":[{"label":"Les fiches valeur et leurs graphiques","href":"/actions"},{"label":"Le scanner technique","href":"/scanner"},{"label":"Notre méthodologie des signaux","href":"/methodologie"},{"label":"Le classement de liquidité","href":"/liquidite"},{"label":"Le calendrier des dividendes et des assemblées","href":"/calendrier"}],"avertissement":"Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital."}$wb$::jsonb),
         updated_at = now()
   where slug = 'academy-niveau-3-technique';

  raise notice '0267 : leçon 5 du niveau 3 enrichie';
end
$do$;

commit;

